-- Modify "cases" table
ALTER TABLE "moderation"."cases" DROP CONSTRAINT "cases_action_target_check", ADD CONSTRAINT "cases_action_target_check" CHECK ((decision_action IS NULL) OR ((decision_action = 'HIDE'::text) AND (target_kind = ANY (ARRAY['COMMENT'::text, 'FORUM_ENTRY'::text, 'REVIEW'::text, 'CHAT_MESSAGE'::text]))) OR ((decision_action = ANY (ARRAY['WARN'::text, 'BAN'::text])) AND (target_kind = ANY (ARRAY['COMMENT'::text, 'FORUM_ENTRY'::text, 'BUYER'::text, 'REVIEW'::text, 'CHAT_MESSAGE'::text]))) OR ((decision_action = 'TAKEDOWN'::text) AND (target_kind = ANY (ARRAY['POST'::text, 'COMMENT'::text, 'FORUM_ENTRY'::text, 'CHAT_MESSAGE'::text, 'REVIEW_REPLY'::text])))), DROP CONSTRAINT "cases_target_kind_check", ADD CONSTRAINT "cases_target_kind_check" CHECK (target_kind = ANY (ARRAY['POST'::text, 'COMMENT'::text, 'FORUM_ENTRY'::text, 'BUYER'::text, 'REVIEW'::text, 'CHAT_MESSAGE'::text, 'REVIEW_REPLY'::text]));
-- Modify "report_requests" table
ALTER TABLE "moderation"."report_requests" DROP CONSTRAINT "report_requests_pkey", ADD CONSTRAINT "report_requests_reporter_kind_check" CHECK ((reporter_buyer_id IS NOT NULL) <> (reporter_store_id IS NOT NULL)), ADD CONSTRAINT "report_requests_reporter_store_check" CHECK (reporter_store_id > 0), ALTER COLUMN "reporter_buyer_id" DROP NOT NULL, ADD COLUMN "reporter_store_id" bigint NULL, ADD CONSTRAINT "report_requests_buyer_key" UNIQUE ("reporter_buyer_id", "request_id"), ADD CONSTRAINT "report_requests_store_key" UNIQUE ("reporter_store_id", "request_id");
-- Modify "reporter_daily_counts" table
ALTER TABLE "moderation"."reporter_daily_counts" DROP CONSTRAINT "reporter_daily_counts_pkey", ADD CONSTRAINT "reporter_daily_counts_reporter_kind_check" CHECK ((reporter_buyer_id IS NOT NULL) <> (reporter_store_id IS NOT NULL)), ADD CONSTRAINT "reporter_daily_counts_reporter_store_check" CHECK (reporter_store_id > 0), ALTER COLUMN "reporter_buyer_id" DROP NOT NULL, ADD COLUMN "reporter_store_id" bigint NULL, ADD CONSTRAINT "reporter_daily_counts_buyer_key" UNIQUE ("reporter_buyer_id"), ADD CONSTRAINT "reporter_daily_counts_store_key" UNIQUE ("reporter_store_id");
-- Drop index "reports_reporter_time" from table: "reports"
DROP INDEX "moderation"."reports_reporter_time";
-- Modify "reports" table
ALTER TABLE "moderation"."reports" ADD CONSTRAINT "reports_reporter_kind_check" CHECK ((reporter_buyer_id IS NOT NULL) <> (reporter_store_id IS NOT NULL)), ADD CONSTRAINT "reports_reporter_store_check" CHECK (reporter_store_id > 0), ALTER COLUMN "reporter_buyer_id" DROP NOT NULL, ADD COLUMN "reporter_store_id" bigint NULL, ADD CONSTRAINT "reports_case_store_reporter_key" UNIQUE ("case_id", "reporter_store_id");
-- Create index "reports_reporter_time" to table: "reports"
CREATE INDEX "reports_reporter_time" ON "moderation"."reports" ("reporter_buyer_id", "created_at" DESC, "id" DESC) WHERE (reporter_buyer_id IS NOT NULL);
